// test_csb_gfx11.cpp - S11 host test for the RLC clear-state (CSIB) table.
//
// The table is generated by tools/gen_csb_gfx11.py from Linux
// clearstate_gfx11.h + gfx_v11_0.c + amdgpu_gfx.c; these expectations are
// written out by hand from those sources, independent of the generator:
//   - 960 dwords, the preamble/context-control head and the tile/end tail;
//   - the seven SET_CONTEXT_REG extents (count + relative index) exactly as
//     gfx11_SECT_CONTEXT_defs[] lists them, and their placement so packet
//     headers never intrude into the data area;
//   - a sample of repaired dwords with their clearstate_gfx11.h line numbers.

#include <cstdint>
#include <cstdio>
#include <cstdlib>

#include "amd/csb_gfx11_data.h"

namespace {

int g_checks = 0;
int g_fail = 0;

#define CHECK(cond, ...)                                                     \
    do {                                                                     \
        ++g_checks;                                                          \
        if (!(cond)) {                                                       \
            ++g_fail;                                                        \
            std::printf("FAIL %s:%d: ", __FILE__, __LINE__);                 \
            std::printf(__VA_ARGS__);                                        \
            std::printf("\n");                                               \
        }                                                                    \
    } while (0)

constexpr uint32_t packet3(uint32_t op, uint32_t count)
{
    return (3u << 30) | ((count & 0x3FFFu) << 16) | ((op & 0xFFu) << 8);
}

struct Segment {
    uint32_t count;
    uint32_t offset;    // reg_index - 0xA000
};

constexpr Segment kSegments[] = {
    { 215, 0x000 }, { 272, 0x0D8 }, { 4, 0x1F5 }, { 158, 0x1FF },
    { 2, 0x2A0 }, { 1, 0x2A3 }, { 282, 0x2A6 },
};

struct Sample {
    uint32_t index;
    uint32_t value;
    const char *where;
};

// Repaired dwords (previously 0 or shifted out of place), read directly from
// evidence/src/linux-7.2.0/drivers/gpu/drm/amd/amdgpu/clearstate_gfx11.h.
constexpr Sample kSamples[] = {
    { 446, 0x00000002u, "clearstate_gfx11.h:468 SPI_PS_IN_CONTROL" },
    { 454, 0x00000000u, "clearstate_gfx11.h:476 HOLE" },
    { 752, 0x00001000u, "clearstate_gfx11.h:779 PA_SC_LINE_CNTL" },
    { 754, 0x00000005u, "clearstate_gfx11.h:781 PA_SU_VTX_CNTL" },
    { 755, 0x3F800000u, "clearstate_gfx11.h:782 PA_CL_GB_VERT_CLIP_ADJ" },
    { 775, 0xFFFFFFFFu, "clearstate_gfx11.h:802 PA_SC_AA_MASK_X0Y0_X1Y0" },
    { 776, 0xFFFFFFFFu, "clearstate_gfx11.h:803 PA_SC_AA_MASK_X0Y1_X1Y1" },
    { 778, 0x00000003u, "clearstate_gfx11.h:805 PA_SC_BINNER_CNTL_0" },
};

}  // namespace

int main()
{
    const size_t n = sizeof(kCsbGfx11) / sizeof(kCsbGfx11[0]);
    CHECK(n == 960, "kCsbGfx11 has %zu dwords, expected 960", n);

    // Preamble start: PREAMBLE_CNTL(0), BEGIN_CLEAR_STATE,
    // CONTEXT_CONTROL(1), 0x80000000, 0x80000000 (amdgpu_gfx.c:2506-2520).
    const uint32_t head[] = { 0xC0004A00u, 0x20000000u, 0xC0012800u,
                              0x80000000u, 0x80000000u };
    for (size_t i = 0; i < sizeof(head) / sizeof(head[0]); ++i)
        CHECK(kCsbGfx11[i] == head[i], "head[%zu] 0x%08x", i, kCsbGfx11[i]);

    // First extent: SET_CONTEXT_REG with count 215 at relative index 0.
    CHECK(kCsbGfx11[5] == 0xC0D76900u, "first packet 0x%08x", kCsbGfx11[5]);
    CHECK(kCsbGfx11[6] == 0x00000000u, "first offset 0x%08x", kCsbGfx11[6]);

    // Walk every extent. A packet header that lands inside a data area (the
    // old failure mode) desynchronises this scan and trips the checks.
    size_t pos = 5;
    for (const Segment &s : kSegments) {
        CHECK(pos + 2 <= n, "extent header past end of table");
        const uint32_t w = kCsbGfx11[pos];
        CHECK(w == packet3(0x69, s.count), "extent header 0x%08x count %u",
              w, s.count);
        CHECK(((w >> 16) & 0x3FFFu) == s.count, "extent count %u",
              (w >> 16) & 0x3FFFu);
        CHECK(((w >> 8) & 0xFFu) == 0x69u, "extent opcode 0x%x",
              (w >> 8) & 0xFFu);
        CHECK(kCsbGfx11[pos + 1] == s.offset, "extent offset 0x%x",
              kCsbGfx11[pos + 1]);
        pos += 2 + s.count;
    }

    // PA_SC_TILE_STEERING_OVERRIDE (gfx_v11_0.c:888-891): count 1, 0x00d7, 0.
    CHECK(pos == 953, "tile packet at %zu, expected 953", pos);
    CHECK(kCsbGfx11[pos] == packet3(0x69, 1), "tile header 0x%08x",
          kCsbGfx11[pos]);
    CHECK(kCsbGfx11[pos + 1] == 0x000000D7u, "tile offset 0x%08x",
          kCsbGfx11[pos + 1]);
    CHECK(kCsbGfx11[pos + 2] == 0x00000000u, "tile value 0x%08x",
          kCsbGfx11[pos + 2]);
    pos += 3;

    // Preamble end + CLEAR_STATE(0) (amdgpu_gfx.c:2556-2564).
    const uint32_t tail7[] = { 0xC0016900u, 0x000000D7u, 0x00000000u,
                               0xC0004A00u, 0x30000000u, 0xC0001200u,
                               0x00000000u };
    CHECK(pos == n - 4, "end packet at %zu, expected %zu", pos, n - 4);
    for (size_t i = 0; i < 7; ++i)
        CHECK(kCsbGfx11[n - 7 + i] == tail7[i], "tail[%zu] 0x%08x",
              i, kCsbGfx11[n - 7 + i]);
    CHECK(pos + 4 == n, "table does not end after the clear-state packet");

    for (const Sample &s : kSamples) {
        CHECK(s.index < n, "sample index %u out of range", s.index);
        if (s.index >= n)
            continue;
        CHECK(kCsbGfx11[s.index] == s.value,
              "[%u] 0x%08x, expected 0x%08x (%s)", s.index,
              kCsbGfx11[s.index], s.value, s.where);
    }

    if (g_fail == 0)
        std::printf("test_csb_gfx11: %d checks passed\n", g_checks);
    else
        std::printf("test_csb_gfx11: %d/%d checks failed\n", g_fail, g_checks);
    return g_fail == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}
